                allowed = set(RequirementDraft.model_fields) - {"derivation_key", "signal_id"}
                if not isinstance(patch, dict) or not set(patch) <= allowed:
                    raise DomainError(422, "Review proposal contains server-owned fields")
                proposed = {k: current[k] for k in RequirementDraft.model_fields}
